import * as fs from 'fs';
import * as path from 'path';
import * as http from 'http';
import * as mime from 'mime';
import connect = require('connect');
import * as bodyParser from 'body-parser';
import * as querystring from 'querystring';
import serveStatic = require('serve-static');
import {EventEmitter} from 'events';
import Router = require('router');
import {RegistryClient, RegistrationRecord} from "jibo-client-framework";

import {ServiceOptions, JiboServerRequest, JiboServerResponse} from './index';
import {ServiceErrors} from "./DataTypes";

const REFRESH_DURATION = 10000;
const TTL = 30;


class HTTPService extends EventEmitter {
    public app:connect.Server;
    public server:http.Server;
    public staticDir:string;
    public router:Router;
    public record:RegistrationRecord;
    private intervalId;
    /*
     * @description the duration in milliseconds between refreshes (10 seconds)
     * @name HTTPService#refreshDuration
     * @type {Number}
     * @private
     */
    private refreshDuration: number;
    /*
     * @description Time To Live (hop limit) of data which the service transmits.
     * (prevents socket data from circulating indefinitely)
     * @name HTTPService#ttl
     * @type {Number}
     * @private
     */
    private ttl: number;

    constructor(public name:string, public options:ServiceOptions, public rootDir:string) {
        super();
        options.register = options.register === undefined ? true : options.register;
        this.refreshDuration = REFRESH_DURATION;
        this.ttl = TTL;
        this.refresh = this.refresh.bind(this);
    }


    public init(callback: (err?:Error)=>void) {
        this.app = connect();

        this.app.use(bodyParser.json({ limit: '10mb' }));
        this.app.use((req, res, next) => this.parseQueryString(req, res, next));

        this.router = new Router();
        this.routes(<Router>this.router);
        (<any>this.app).use(this.router);

        this.staticDir = path.join(this.rootDir, 'static', this.name);
        this.app.use( serveStatic(this.staticDir) );  // html and friends

        this.server = http.createServer(this.app);
        this.server.listen(this.options.port, () => {
            this.port = this.server.address().port;
            console.log(`${this.name} service listening on port ${this.port}`);
            if(this.name !== 'registry' && this.options.register) {
                this.record = {
                    name: this.name,
                    host: 'localhost',
                    port: this.port,
                    path: '/',
                    ttl: this.ttl,
                    tls: ''
                };
                // since the registry service is persistent on the robot, clear out
                // any old records first
                RegistryClient.instance.deleteRecord(this.record, (error:Error) => {
                    if (error) {
                        console.error('RegistryClient.deleteRecord', error);
                    }
                    RegistryClient.instance.addNewRecord(this.record, (error:Error) => {
                        //set a refresh of 10 seconds
                        this.intervalId = setInterval(this.refresh, this.refreshDuration);
                        // don't report upwards any errors
                        // if there is a registry problem (e.g. registry service isn't up)
                        // it should resolve itself during the refreshes
                        callback();
                    });
                });
            }
            else {
                callback();
            }
        });
    }

    public refresh() {
        RegistryClient.instance.editRecord(this.record, (error) => {
            if (error) {
                // [SDK-848] if registry service restarted the entry
                // will have disappeared and has to be added back
                console.log('readding registry record', this.record);
                RegistryClient.instance.addNewRecord(this.record, () => {
                    return;
                });
            } else {
                return;
            }
        });
    }

    get port():number {
        return this.options.port ? this.options.port : 0;
    }

    set port(value:number) {
        this.options.port = value;
    }

    public enableDebug() {
        this.app.use( (req, res, next) => {
            console.log(this.name, req.method, req.url);
            next();
        });
    }

    public parseQueryString(req:JiboServerRequest, res, next) {
        req.query = querystring.parse((<any>req)._parsedUrl.query);
        next();
    }

    public routes(url:Router):void {
        url.get('/_M_/errors', this.onErrors.bind(this));
        url.post('/_M_/system/backup', this.onBackupRequest.bind(this));
        url.post('/_M_/system/restore', this.onRestoreRequest.bind(this));
        url.post('/_M_/system/wipe', this.onWipeRequest.bind(this));
        return;
    }


    public finish(res:JiboServerResponse, err?:Error, data?:any, contentType?:string, statusCode?:number):void {
        if (err) {
            res.statusCode = 500;
            res.end('Error: ' + err);
            console.error(err);
        } else {
            statusCode = statusCode || 200;
            if (contentType) {
                res.writeHead(statusCode, {'Content-Type': contentType});
            } else {
                res.writeHead(statusCode);
            }
            if (data) {
                res.end(data);
            } else {
                res.end();
            }
        }
    }


    public finishNoContent(res:JiboServerResponse, status?:number, err?:Error) {
        this.finish(res, err, null, null, status);
    }


    public sendFile(res:JiboServerResponse, filename:string, contentType?:string):void {
        console.log(this.name, 'sending ' + filename);
        contentType = contentType || mime.lookup(filename);
        let file = fs.createReadStream(filename);
        file.on('open', () => {
            res.writeHead(200, {'Content-Type': contentType});
            file.pipe(res);
        });
        file.on('error', (err) => {
            this.finish(res, err);
        });
    }


    public sendJson(res:JiboServerResponse, json:Object|string, statusCode?:number):void {
        let err;
        if (typeof json !== 'string') {
            try {
                json = JSON.stringify(json);
            }
            catch (e) {
                console.error('JSON.stringify: ', e);
                json = null;
                err = e;
            }
        }
        this.finish(res, err, json, 'application/json', statusCode);
    }

    public destroy() {
        clearInterval(this.intervalId);
    }

    /*
     * @description Function called with request and response when service receives an error message.
     * Replies with empty 200 response.
     * should be overridden on a by-service basis.
     * @method HTTPService#onErrors
     * @param req {JiboServerRequest} request to service
     * @param res {JiboServerResponse} response to send from service.
     * @protected
     */
    protected onErrors(req:JiboServerRequest, res:JiboServerResponse) {
        const data = new ServiceErrors();
        this.sendJson(res, data, 200);
        return;
    }

    /*
     * @description Base function for service backup. Each service that has files to backup
     * should override it.
     * Replies with empty 204 response.
     * @method HTTPService#onBackupRequest
     * @param req {JiboServerRequest} request to service
     *                                param "directory" -- directory to backup to
     *                                param "dataDirectory" (optional) -- directory where data is stored
     *                                  otherwise, use service's own data directory
     * @param res {JiboServerResponse} response to send from service.
     * @protected
     */
    protected onBackupRequest(req:JiboServerRequest, res:JiboServerResponse) {

        this.sendJson(res, {}, 204);

        return;
    }

    /*
     * @description Base function for wipe service. Each service that
     * has files to wipe should override it.
     * Replies with empty 204 response.
     * @method HTTPService#onWipeRequest
     * @param req {JiboServerRequest} request to service
     *                                param "dataDirectory" (optional) -- directory where data is stored
     *                                  otherwise, use service's own data directory
     * @param res {JiboServerResponse} response to send from service.
     * @protected
     */
    protected onWipeRequest(req:JiboServerRequest, res:JiboServerResponse) {

        this.sendJson(res, {}, 204);

        return;
    }

    /*
     * @description Base function for service backup restore. Each service that
     * has files to restore should override it.
     * Replies with empty 204 response.
     * @method HTTPService#onBackupRequest
     * @param req {JiboServerRequest} request to service
     *                                param "directory" -- directory where backup is
     *                                param "dataDirectory" (optional) -- directory where data is stored
     *                                  otherwise, use service's own data directory
     * @param res {JiboServerResponse} response to send from service.
     * @protected
     */
    protected onRestoreRequest(req:JiboServerRequest, res:JiboServerResponse) {

        this.sendJson(res, {}, 204);

        return;
    }
}


export default HTTPService;
