import _HTTPService from "./HTTPService";
import _HTTPServiceDebug from "./HTTPServiceDebug";
import _HTTPWSService from "./HTTPWSService";
import _HTTPWServiceDebug from "./HTTPWSServiceDebug";
import {HTTPClient as _HTTPClient} from "jibo-client-framework";
import {WSClient as _WSClient} from "jibo-client-framework";
import {RegistryClient as _RegistryClient} from "jibo-client-framework";


export class HTTPClient extends _HTTPClient {
    constructor(host:string, port:number) {
        super(host, port);
    }
}

export class WSClient extends _WSClient {
    constructor(host:string) {
        super(host);
    }
}

export class RegistryClient extends _RegistryClient {
    constructor(host:string, port:number) {
        super(host, port);
    }

    public static get instance():RegistryClient {
        return _RegistryClient.instance;
    }
}

export class HTTPServiceDebug extends _HTTPServiceDebug {
    constructor(options:ServiceOptions, staticDir:string) {
        super(options, staticDir);
    }
}

export class HTTPWSServiceDebug extends _HTTPWServiceDebug {
    constructor(options:ServiceOptions, staticDir:string) {
        super(options, staticDir);
    }
}

export abstract class HTTPWSService extends _HTTPWSService {
    constructor(name:string, options:ServiceOptions, staticDir:string) {
        super(name, options, staticDir);
    }
}

export abstract class HTTPService extends _HTTPService {
    constructor(name:string, options:ServiceOptions, staticDir:string) {
        super(name, options, staticDir);
    }
}


import * as http from 'http';

export type HandlerFunction = (req: http.IncomingMessage, res: JiboServerResponse, next: Function)=>void;

export interface JiboServerRequest extends http.ServerRequest {
    params: any;
    query: any;
    body: any;
}

export interface JiboServerResponse extends http.ServerResponse {
}

export interface ServiceOptions {
    port:number;
    register?:boolean;
}

export interface RegistrationRecord {
    name:string;
    host:string;
    port:number;
    path:string;
    ttl?:number;
    tls?:string;
}

export default {};
